def solve_small(n):
    # Find all triples {x, y, z} in {1, ..., n} such that
    # x < y < z, x+y+z is even, and x+y >= z+2
    triples = []
    for x in range(1, n + 1):
        for y in range(x + 1, n + 1):
            for z in range(y + 1, n + 1):
                if (x + y + z) % 2 == 0 and (x + y >= z + 2):
                    triples.append((x, y, z))

    # Now find the maximum size of a subset A of {1, ..., n}
    # that does not contain any of these triples.
    # This is a maximum independent set problem on a hypergraph.
    # Since n is small, we can use backtracking or bitmask.

    from itertools import combinations

    max_size = 0
    for r in range(n, 0, -1):
        found_any = False
        for subset in combinations(range(1, n + 1), r):
            subset_set = set(subset)
            contains_triple = False
            for t in triples:
                if t[0] in subset_set and t[1] in subset_set and t[2] in subset_set:
                    contains_triple = True
                    break
            if not contains_triple:
                max_size = r
                found_any = True
                break
        if found_any:
            break
    return max_size

