def get_f(n):
    triples = []
    for x in range(1, n + 1):
        for y in range(x + 1, n + 1):
            for z in range(y + 1, n + 1):
                if (x + y + z) % 2 == 0 and (x + y >= z + 2):
                    triples.append((x, y, z))

    # Use a recursive function with pruning to find the maximum size of A
    max_size = 0

    def solve(idx, current_subset):
        nonlocal max_size
        if idx > n:
            max_size = max(max_size, len(current_subset))
            return

        # Pruning
        if len(current_subset) + (n - idx + 1) <= max_size:
            return

        # Option 1: Include idx
        can_include = True
        for i in range(len(current_subset)):
            for j in range(i + 1, len(current_subset)):
                x, y = current_subset[i], current_subset[j]
                # x < y < idx
                if (x + y + idx) % 2 == 0 and (x + y >= idx + 2):
                    can_include = False
                    break
            if not can_include: break

        if can_include:
            solve(idx + 1, current_subset + [idx])

        # Option 2: Exclude idx
        solve(idx + 1, current_subset)

    solve(1, [])
    return max_size

